#!/usr/bin/env node
// tools/health/map.mjs — GENERATED codebase-health map + redundancy detector for LeanBCH.
//
// Pure text/parse over LeanBCH/**/*.lean (+ the root LeanBCH.lean). No deps, no `lake build`.
// Emits two committed artifacts:
//   • tools/health/REPORT.md   — human-readable
//   • tools/health/index.json  — machine-queryable
// Regenerate:  node tools/health/map.mjs
//
// The point: an always-true "what exists / what's dead / what's duplicated" query surface, so
// AI agents query it BEFORE building (prevents duplication) and drift in the un-kernel-checked
// layer (dead files, dupes, escape hatches, claim-prose) is visible in a diff. See README.md.
//
// DO NOT hand-edit REPORT.md / index.json — they are regenerated by this script. Everything is
// sorted deterministically so regeneration produces a minimal, meaningful git diff (no timestamps).

import { readdirSync, statSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve, relative, basename, sep } from 'node:path';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url)); // <repo>/tools/health
const REPO = resolve(SCRIPT_DIR, '..', '..');               // <repo>

// ---------------------------------------------------------------------------
// 0. Collect source files: the root LeanBCH.lean + every LeanBCH/**/*.lean.
// ---------------------------------------------------------------------------
function walk(dir, acc) {
  for (const name of readdirSync(dir)) {
    const p = resolve(dir, name);
    const st = statSync(p);
    if (st.isDirectory()) walk(p, acc);
    else if (st.isFile() && name.endsWith('.lean')) acc.push(p);
  }
  return acc;
}

const files = [];
const rootModule = resolve(REPO, 'LeanBCH.lean');
try { if (statSync(rootModule).isFile()) files.push(rootModule); } catch {}
walk(resolve(REPO, 'LeanBCH'), files);
files.sort();

// path (relative to repo, forward slashes) <-> module name.
const relPath = (abs) => relative(REPO, abs).split(sep).join('/');
const moduleOfPath = (rel) => rel.replace(/\.lean$/, '').split('/').join('.');
const pathOfModule = (mod) => mod.split('.').join('/') + '.lean';

// ---------------------------------------------------------------------------
// 1. Comment/string stripping.
//    Produce, per line: `code` (comments+strings blanked to spaces, line numbers
//    preserved) and `comment` (only the comment text). Handles nested `/- -/`,
//    doc comments `/-- -/` `/-! -/`, `--` line comments, and "..." strings.
// ---------------------------------------------------------------------------
function splitCommentsAndCode(src) {
  const codeLines = [];
  const commentLines = [];
  let code = '';
  let comment = '';
  let block = 0;       // nesting depth of /- -/
  let inString = false;
  const pushLine = () => { codeLines.push(code); commentLines.push(comment); code = ''; comment = ''; };
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (c === '\n') { pushLine(); continue; }
    if (block > 0) {
      if (c === '/' && src[i + 1] === '-') { block++; comment += '  '; i++; continue; }
      if (c === '-' && src[i + 1] === '/') { block--; comment += '  '; i++; continue; }
      comment += c;
      continue;
    }
    if (inString) {
      code += ' ';
      if (c === '\\') { code += ' '; i++; continue; } // skip escaped char
      if (c === '"') inString = false;
      continue;
    }
    // not in comment/string
    if (c === '-' && src[i + 1] === '-') {           // line comment to EOL
      let j = i + 2;
      while (j < src.length && src[j] !== '\n') { comment += src[j]; j++; }
      i = j - 1;
      continue;
    }
    if (c === '/' && src[i + 1] === '-') { block++; comment += '  '; i++; continue; } // block/doc open
    if (c === '"') { inString = true; code += ' '; continue; }
    code += c;
  }
  pushLine(); // trailing line (no final newline)
  return { codeLines, commentLines };
}

// Blank out inline `...`-quoted spans in a code line (Lean name/syntax quotes; also a
// belt-and-suspenders guard so a backtick-wrapped token is never counted as a real use).
function stripBackticks(line) {
  return line.replace(/`[^`]*`/g, (m) => ' '.repeat(m.length));
}

// ---------------------------------------------------------------------------
// Per-file parse.
// ---------------------------------------------------------------------------
const DECL_KINDS = ['theorem', 'lemma', 'def', 'abbrev', 'structure', 'inductive'];
const MODIFIERS = '(?:private|protected|noncomputable|partial|unsafe|scoped|local|nonrec)';
const DECL_RE = new RegExp(
  `^\\s*(?:@\\[[^\\]]*\\]\\s*)*(?:${MODIFIERS}\\s+)*(${DECL_KINDS.join('|')})\\s+([^\\s:({\\[⦃⟨]+)`
);
const CLAIM_WORDS = [
  'proven', 'sound', 'complete', 'verified', '0 sorry', 'sorry-free',
  'byte-for-byte', 'floor', 'exact', 'keystone',
];
// Escape-hatch token detectors run over the code (comments/strings/backticks removed).
const ESCAPES = {
  sorry:         /\bsorry\b/,
  admit:         /\badmit\b/,
  native_decide: /\bnative_decide\b/,
  partial:       /\bpartial\b/,
  unsafe:        /\bunsafe\b/,
  axiom:         /^\s*(?:private\s+|protected\s+)*axiom\b/,
};

const modules = [];               // { module, path, loc, imports:[mod], reachable }
const pathToModule = new Map();
const moduleToPath = new Map();
const declarations = [];          // { name, kind, namespace, fullName, file, line, signature }
const escapeHits = { sorry: [], admit: [], native_decide: [], partial: [], unsafe: [], axiom: [] };
const decideByFile = [];          // { file, count }
const claims = [];                // { word, file, line, text }

let totalLoc = 0;

for (const abs of files) {
  const rel = relPath(abs);
  const mod = moduleOfPath(rel);
  pathToModule.set(rel, mod);
  moduleToPath.set(mod, rel);

  const src = readFileSync(abs, 'utf8');
  const rawLines = src.split('\n');
  // a trailing newline yields a final '' element; count physical lines of content.
  const loc = rawLines.length > 0 && rawLines[rawLines.length - 1] === ''
    ? rawLines.length - 1 : rawLines.length;
  totalLoc += loc;

  const { codeLines, commentLines } = splitCommentsAndCode(src);

  // namespace / section / mutual stack. Only `namespace` frames name declarations.
  const stack = []; // { kind:'namespace'|'section'|'mutual', endName:string|null, comps:[...] }
  const currentNamespace = () =>
    stack.filter((f) => f.kind === 'namespace').flatMap((f) => f.comps).join('.');

  const imports = [];
  let decideCount = 0;

  for (let li = 0; li < codeLines.length; li++) {
    const codeRaw = codeLines[li];
    const code = stripBackticks(codeRaw);
    const lineNo = li + 1;

    // -- imports --
    const imp = /^\s*import\s+([A-Za-z0-9_.]+)/.exec(code);
    if (imp) { if (imp[1].startsWith('LeanBCH')) imports.push(imp[1]); continue; }

    // -- namespace / section / mutual / end --
    let m;
    if ((m = /^\s*namespace\s+([A-Za-z0-9_.'!?]+)/.exec(code))) {
      stack.push({ kind: 'namespace', endName: m[1], comps: m[1].split('.') });
      continue;
    }
    if ((m = /^\s*section(?:\s+([A-Za-z0-9_.'!?]+))?\s*$/.exec(code))) {
      stack.push({ kind: 'section', endName: m[1] || null, comps: [] });
      continue;
    }
    if (/^\s*mutual\b/.test(code)) {
      stack.push({ kind: 'mutual', endName: null, comps: [] });
      continue;
    }
    if ((m = /^\s*end(?:\s+([A-Za-z0-9_.'!?]+))?\s*$/.exec(code))) {
      const name = m[1] || null;
      if (name === null) { if (stack.length) stack.pop(); }
      else {
        // pop down to (and including) the nearest frame whose endName matches.
        let idx = -1;
        for (let k = stack.length - 1; k >= 0; k--) { if (stack[k].endName === name) { idx = k; break; } }
        if (idx >= 0) stack.length = idx; else if (stack.length) stack.pop();
      }
      continue;
    }

    // -- declarations --
    if ((m = DECL_RE.exec(code))) {
      const kind = m[1] === 'lemma' ? 'lemma' : m[1];
      let nameTok = m[2];
      // trim trailing separators that can cling to the token
      nameTok = nameTok.replace(/[,;]+$/, '');
      const simpleName = nameTok.split('.').pop();
      const ns = currentNamespace();
      const full = nameTok.includes('.')
        ? (ns ? ns + '.' + nameTok : nameTok)
        : (ns ? ns + '.' + nameTok : nameTok);
      declarations.push({
        name: simpleName,
        kind,
        namespace: ns,
        fullName: full,
        file: rel,
        line: lineNo,
        signature: codeRaw.trim(), // best-effort: first signature line only
      });
    }

    // -- escape-hatch tokens (over comment/string/backtick-stripped code) --
    for (const [key, re] of Object.entries(ESCAPES)) {
      if (re.test(code)) {
        escapeHits[key].push({ file: rel, line: lineNo, text: rawLines[li].trim() });
      }
    }
    // -- per-file `decide` count (kernel decide; native_decide excluded by \b) --
    const dm = code.match(/\bdecide\b/g);
    if (dm) decideCount += dm.length;
  }

  // -- claim scan over COMMENT text (prose worklist, not verified) --
  for (let li = 0; li < commentLines.length; li++) {
    const ctext = commentLines[li];
    if (!ctext) continue;
    const lc = ctext.toLowerCase();
    const hit = [];
    for (const w of CLAIM_WORDS) {
      let re;
      if (/[ -]/.test(w)) re = new RegExp(w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
      else re = new RegExp('\\b' + w, 'i'); // prefix boundary → also catches soundness/completeness/etc.
      if (re.test(lc)) hit.push(w);
    }
    if (hit.length) {
      claims.push({ words: hit, file: rel, line: li + 1, text: rawLines[li].trim() });
    }
  }

  if (decideCount > 0) decideByFile.push({ file: rel, count: decideCount });
  modules.push({ module: mod, path: rel, loc, imports: [...new Set(imports)].sort(), reachable: false });
}

// ---------------------------------------------------------------------------
// 2. Module DAG + reachability from roots.
// ---------------------------------------------------------------------------
const ROOTS = ['LeanBCH', 'LeanBCH.Opt', 'LeanBCH.Validation'].filter((r) => moduleToPath.has(r));
const modByName = new Map(modules.map((m) => [m.module, m]));
const reach = new Set();
const queue = [...ROOTS];
while (queue.length) {
  const cur = queue.shift();
  if (reach.has(cur)) continue;
  reach.add(cur);
  const node = modByName.get(cur);
  if (!node) continue;
  for (const imp of node.imports) if (!reach.has(imp)) queue.push(imp);
}
for (const m of modules) m.reachable = reach.has(m.module);
const orphans = modules.filter((m) => !m.reachable).map((m) => m.path).sort();

// broken imports (import target has no file) — surfaced for completeness.
const brokenImports = [];
for (const m of modules) {
  for (const imp of m.imports) {
    if (!moduleToPath.has(imp)) brokenImports.push({ from: m.path, imports: imp });
  }
}

// Optimizer VM-interface contract (Phase 3): LeanBCH.Opt.* is a distinct LAYER over the VM. It may
// reach the core ONLY through this small, deliberate surface — the seam that survives the leanbch-opt
// package split. A new cross-import outside this set means the optimizer grew a hidden dependency on
// VM internals; that is a design regression and FAILS the health gate.
const OPT_VM_INTERFACE = new Set([
  'LeanBCH.VM.Straightline', 'LeanBCH.VM.RunStraight', 'LeanBCH.VM.Instr',
  'LeanBCH.VM.Extended', 'LeanBCH.Cost.Arith',
]);
const optInterfaceViolations = [];
for (const m of modules) {
  if (!(m.module === 'LeanBCH.Opt' || m.module.startsWith('LeanBCH.Opt.'))) continue;
  for (const imp of m.imports) {
    if (imp === 'LeanBCH.Opt' || imp.startsWith('LeanBCH.Opt.')) continue; // intra-optimizer: fine
    if (!imp.startsWith('LeanBCH')) continue;                              // core Lean/Std: fine
    if (!OPT_VM_INTERFACE.has(imp)) optInterfaceViolations.push({ from: m.path, imports: imp });
  }
}

// ---------------------------------------------------------------------------
// 3. Duplication suspects.
// ---------------------------------------------------------------------------
const byName = new Map();
for (const d of declarations) {
  if (!byName.has(d.name)) byName.set(d.name, []);
  byName.get(d.name).push(d);
}
const dupNames = [];
for (const [name, decls] of byName) {
  const distinctFiles = new Set(decls.map((d) => d.file));
  if (distinctFiles.size >= 2) {
    dupNames.push({
      name,
      count: decls.length,
      files: distinctFiles.size,
      locations: decls
        .map((d) => ({ file: d.file, line: d.line, kind: d.kind, fullName: d.fullName }))
        .sort((a, b) => (a.file + a.line).localeCompare(b.file + b.line)),
    });
  }
}
dupNames.sort((a, b) => b.files - a.files || b.count - a.count || a.name.localeCompare(b.name));

const byBase = new Map();
for (const m of modules) {
  const b = basename(m.path);
  if (!byBase.has(b)) byBase.set(b, []);
  byBase.get(b).push(m.path);
}
const dupBasenames = [];
for (const [b, paths] of byBase) {
  if (paths.length >= 2) dupBasenames.push({ basename: b, files: paths.slice().sort() });
}
dupBasenames.sort((a, b) => a.basename.localeCompare(b.basename));

// ---------------------------------------------------------------------------
// 4. Sort escape-hatch hits + tally.
// ---------------------------------------------------------------------------
const bfl = (a, b) => a.file.localeCompare(b.file) || a.line - b.line;
for (const k of Object.keys(escapeHits)) escapeHits[k].sort(bfl);
decideByFile.sort((a, b) => b.count - a.count || a.file.localeCompare(b.file));
claims.sort(bfl);
declarations.sort(bfl);
modules.sort((a, b) => a.path.localeCompare(b.path));

const escapeTotals = Object.fromEntries(Object.entries(escapeHits).map(([k, v]) => [k, v.length]));
// "headline" hatches that MUST be zero for a verified library:
const headline = escapeTotals.sorry + escapeTotals.admit + escapeTotals.native_decide + escapeTotals.partial;
// "real escape hatches" = every non-decide proof-term hatch.
const realEscapeHatches = headline + escapeTotals.unsafe + escapeTotals.axiom;

// ---------------------------------------------------------------------------
// 5. VERDICT.
// ---------------------------------------------------------------------------
const cleanHeadline = headline === 0;
const verdict = cleanHeadline
  ? `CLEAN — 0 sorry / 0 admit / 0 native_decide / 0 partial across ${files.length} files`
    + (escapeTotals.axiom || escapeTotals.unsafe
        ? ` (note ${escapeTotals.axiom} axiom / ${escapeTotals.unsafe} unsafe — review)` : '')
    + `; ${orphans.length} orphan file(s), ${dupNames.length} duplicate name(s).`
  : `DIRTY — ${headline} headline escape hatch(es) present (sorry/admit/native_decide/partial). INVESTIGATE.`;

// ---------------------------------------------------------------------------
// 6. Emit index.json.
// ---------------------------------------------------------------------------
const summary = {
  files: files.length,
  loc: totalLoc,
  declarations: declarations.length,
  orphans: orphans.length,
  duplicateNames: dupNames.length,
  duplicateBasenames: dupBasenames.length,
  realEscapeHatches,
  headlineEscapeHatches: headline,
  brokenImports: brokenImports.length,
  optInterfaceViolations: optInterfaceViolations.length,
  verdict,
};

const index = {
  note: 'GENERATED by tools/health/map.mjs — DO NOT EDIT. Regenerate: node tools/health/map.mjs',
  schemaVersion: 1,
  roots: ROOTS,
  summary,
  modules,
  orphans,
  brokenImports,
  optInterface: { allowed: [...OPT_VM_INTERFACE].sort(), violations: optInterfaceViolations },
  declarations,
  duplication: { names: dupNames, basenames: dupBasenames },
  escapeHatches: { totals: escapeTotals, byKind: escapeHits, decideByFile },
  claims,
};

writeFileSync(resolve(SCRIPT_DIR, 'index.json'), JSON.stringify(index, null, 2) + '\n');

// ---------------------------------------------------------------------------
// 7. Emit REPORT.md.
// ---------------------------------------------------------------------------
const L = [];
const p = (s = '') => L.push(s);

p('# LeanBCH codebase-health map');
p('');
p('> GENERATED by `tools/health/map.mjs` — **do not hand-edit**. Regenerate: `node tools/health/map.mjs`.');
p('> This is the always-true "what exists / what is dead / what is duplicated" query surface.');
p('> Query `tools/health/index.json` (machine-readable) BEFORE defining or proving something.');
p('');
p('## Summary');
p('');
p('| metric | value |');
p('| --- | --- |');
p(`| source files | ${summary.files} |`);
p(`| total LOC | ${summary.loc} |`);
p(`| declarations | ${summary.declarations} |`);
p(`| orphan files (dead) | ${summary.orphans} |`);
p(`| duplicate decl names | ${summary.duplicateNames} |`);
p(`| duplicate basenames | ${summary.duplicateBasenames} |`);
p(`| real escape hatches | ${summary.realEscapeHatches} |`);
p(`| headline hatches (sorry/admit/native_decide/partial) | ${summary.headlineEscapeHatches} |`);
p(`| broken imports | ${summary.brokenImports} |`);
p('');
p(`**VERDICT:** ${verdict}`);
p('');

p('## 1. Module DAG + orphans');
p('');
p(`Roots: ${ROOTS.map((r) => '`' + r + '`').join(', ')}. A file NOT transitively imported from a root is an ORPHAN (dead file).`);
p('');
if (orphans.length === 0) p('_No orphans — every source file is reachable from a root._');
else { p('**ORPHANS (dead files — not reachable from any root):**'); p(''); for (const o of orphans) p(`- \`${o}\``); }
p('');
if (brokenImports.length) {
  p('**BROKEN IMPORTS (import target has no matching file):**'); p('');
  for (const b of brokenImports) p(`- \`${b.from}\` imports \`${b.imports}\` (no file)`); p('');
}
p('<details><summary>Full module → imports table</summary>'); p('');
p('| module | file | LOC | reach | # imports |');
p('| --- | --- | ---: | :---: | ---: |');
for (const m of modules) p(`| \`${m.module}\` | \`${m.path}\` | ${m.loc} | ${m.reachable ? 'yes' : 'ORPHAN'} | ${m.imports.length} |`);
p(''); p('</details>'); p('');

p('## 2. Declaration index');
p('');
p(`${declarations.length} top-level declarations (\`theorem\`/\`lemma\`/\`def\`/\`abbrev\`/\`structure\`/\`inductive\`).`);
p('The "does it already exist?" query surface. Signatures are **best-effort** (first line only;');
p('multi-line signatures are truncated). Full detail lives in `index.json`.');
p('');
p('Kind tally: ' + Object.entries(
  declarations.reduce((a, d) => ((a[d.kind] = (a[d.kind] || 0) + 1), a), {})
).sort().map(([k, v]) => `\`${k}\`=${v}`).join(', ') + '.');
p('');
p('<details><summary>All declarations (file:line — kind — fullName)</summary>'); p('');
p('```');
for (const d of declarations) p(`${d.file}:${d.line}  ${d.kind}  ${d.fullName}`);
p('```'); p('</details>'); p('');

p('## 3. Duplication suspects');
p('');
p('**Suspects for human review — some are legitimate** (same simple name in different namespaces,');
p('e.g. `add`/`zero`/`map`). The tool flags; a human decides.');
p('');
p(`### 3a. Simple names defined in ≥2 files (${dupNames.length})`);
p('');
if (dupNames.length === 0) p('_None._');
else {
  for (const d of dupNames) {
    p(`- \`${d.name}\` — ${d.count} decls across ${d.files} files:`);
    for (const loc of d.locations) p(`    - \`${loc.file}:${loc.line}\` (${loc.kind}) \`${loc.fullName}\``);
  }
}
p('');
p(`### 3b. Same basename in different directories (${dupBasenames.length})`);
p('');
if (dupBasenames.length === 0) p('_None._');
else for (const b of dupBasenames) p(`- \`${b.basename}\`: ${b.files.map((f) => '`' + f + '`').join(', ')}`);
p('');

p('## 4. Escape-hatch scan');
p('');
p('Real proof-term uses only — comments, doc-prose, strings, and backtick-quoted tokens are excluded.');
p('The whole project should show ZERO `sorry`/`admit`/`native_decide`/`partial`.');
p('');
p('| hatch | count |');
p('| --- | ---: |');
for (const k of ['sorry', 'admit', 'native_decide', 'partial', 'unsafe', 'axiom']) p(`| \`${k}\` | ${escapeTotals[k]} |`);
p('');
if (headline === 0) p('**HEADLINE: 0 real `sorry`/`admit`/`native_decide`/`partial`.** (Verified by parse.)');
else p(`**HEADLINE: ${headline} real headline escape hatch(es) present — INVESTIGATE.**`);
p('');
for (const k of ['sorry', 'admit', 'native_decide', 'partial', 'unsafe', 'axiom']) {
  if (escapeHits[k].length) {
    p(`Locations for \`${k}\`:`);
    for (const h of escapeHits[k]) p(`- \`${h.file}:${h.line}\` — ${h.text}`);
    p('');
  }
}
p('### Per-file `decide` count (kernel `decide` is fine; concentration is worth a look)');
p('');
if (decideByFile.length === 0) p('_No `decide` uses found._');
else {
  p('| file | `decide` count |');
  p('| --- | ---: |');
  for (const d of decideByFile) p(`| \`${d.file}\` | ${d.count} |`);
}
p('');

p('## 5. Claim scan (surface, NOT verified)');
p('');
p('Comment/doc lines containing strong claim words — a worklist for a human/adversarial reviewer to');
p(`check claims against reality. Words: ${CLAIM_WORDS.map((w) => '`' + w + '`').join(', ')}. ${claims.length} lines.`);
p('This is the un-gateable drift class; the tool only makes it visible.');
p('');
p('<details><summary>All claim lines (file:line — words — text)</summary>'); p('');
p('```');
for (const c of claims) p(`${c.file}:${c.line}  [${c.words.join(',')}]  ${c.text}`);
p('```'); p('</details>'); p('');

p('---');
p('');
p('_Generated by `tools/health/map.mjs`. FAIL-gate candidates to promote later: any real escape hatch');
p('(`sorry`/`admit`/`native_decide`/`partial`) and any NEW orphan file. See `tools/health/README.md`._');

writeFileSync(resolve(SCRIPT_DIR, 'REPORT.md'), L.join('\n') + '\n');

// ---------------------------------------------------------------------------
// 8. Console summary (also echoed by tools/opt-ci/verify.sh).
// ---------------------------------------------------------------------------
console.log('LeanBCH health map regenerated:');
console.log(`  files=${summary.files} loc=${summary.loc} decls=${summary.declarations}`);
console.log(`  orphans=${summary.orphans} dupNames=${summary.duplicateNames} dupBasenames=${summary.duplicateBasenames}`);
console.log(`  escape-hatches: sorry=${escapeTotals.sorry} admit=${escapeTotals.admit} native_decide=${escapeTotals.native_decide} partial=${escapeTotals.partial} unsafe=${escapeTotals.unsafe} axiom=${escapeTotals.axiom}`);
console.log(`  opt-VM-interface violations=${optInterfaceViolations.length}` +
  (optInterfaceViolations.length ? ' → ' + optInterfaceViolations.map((v) => `${v.from}⇒${v.imports}`).join(', ') : ' (optimizer reaches the VM only through the allowed seam)'));
console.log(`  VERDICT: ${verdict}`);
console.log('  wrote tools/health/REPORT.md, tools/health/index.json');
